        void select(String key){if(key.equals("main")){dialog.dismiss();return;}history.clear();active=key;state=new State();state.page=key.equals("home")||key.equals("favorites")||key.equals("search")||key.equals("settings")?key:key.equals("match")?"matches":"list";state.kind=key;state.title=tabName(key);render();}
