        void render(){generation++;handler.removeCallbacksAndMessages(null);root=Ui.column(a);root.setBackgroundColor(Ui.bg(a));root.addView(top(),new LinearLayout.LayoutParams(-1,Ui.dp(a,62)));scroll=new ScrollView(a);scroll.setFillViewport(true);content=Ui.column(a);content.setPadding(Ui.dp(a,12),0,Ui.dp(a,12),Ui.dp(a,24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));tabs=nav();root.addView(tabs,new LinearLayout.LayoutParams(-1,Ui.dp(a,72)));dialog.setContentView(root);
            switch(state.page){case "home":home();break;case "list":catalogue();break;case "detail":detail();break;case "matches":matches();break;case "favorites":favorites();break;case "search":search();break;case "settings":settings();break;}
        }
        View top(){LinearLayout r=Ui.row(a);r.setPadding(Ui.dp(a,4),0,Ui.dp(a,4),0);r.setBackgroundColor(Ui.surface(a));TextView b=text(history.isEmpty()?"⌂":"›",30,true);b.setGravity(Gravity.CENTER);b.setContentDescription(history.isEmpty()?"التبويبات الرئيسية":"رجوع");b.setOnClickListener(v->back());r.addView(b,new LinearLayout.LayoutParams(Ui.dp(a,48),-1));LinearLayout title=Ui.column(a);TextView t=text(state.title,18,true);t.setMaxLines(1);t.setEllipsize(TextUtils.TruncateAt.END);title.addView(t);TextView sub=text("AWR WORLD  /  عالم المصادر",10,true);sub.setTextColor(Ui.ACCENT);title.addView(sub);r.addView(title,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(a,"search",Ui.ACCENT);icon.setPadding(12,12,12,12);icon.setContentDescription("البحث في كل المصادر");icon.setOnClickListener(v->select("search"));r.addView(icon,new LinearLayout.LayoutParams(Ui.dp(a,46),Ui.dp(a,46)));return r;}
        HorizontalScrollView nav(){HorizontalScrollView h=new HorizontalScrollView(a);h.setHorizontalScrollBarEnabled(true);h.setBackgroundColor(Ui.surface(a));h.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);LinearLayout row=Ui.row(a);View selected=null;for(int i=0;i<TAB_KEYS.length;i++){final String key=TAB_KEYS[i];boolean on=active.equals(key);LinearLayout cell=Ui.column(a);cell.setGravity(Gravity.CENTER);cell.setSelected(on);cell.setContentDescription(TAB_NAMES[i]);Ui.clickable(cell,on?0x20eec60a:Color.TRANSPARENT,12);cell.addView(new Ui.Icon(a,TAB_ICONS[i],on?Ui.ACCENT:Ui.muted(a)),new LinearLayout.LayoutParams(Ui.dp(a,23),Ui.dp(a,23)));TextView label=text(TAB_NAMES[i],11,on);label.setTextColor(on?Ui.ACCENT:Ui.muted(a));label.setGravity(Gravity.CENTER);cell.addView(label);cell.setOnClickListener(v->select(key));row.addView(cell,new LinearLayout.LayoutParams(Ui.dp(a,key.equals("main")?125:83),Ui.dp(a,67)));if(on)selected=cell;}h.addView(row);View target=selected;if(target!=null)h.post(()->h.smoothScrollTo(Math.max(0,target.getLeft()-(h.getWidth()-target.getWidth())/2),0));return h;}
        TextView text(String s,int size,boolean bold){TextView t=Ui.text(a,s,size+(prefs.getBoolean("large_text",false)?2:0),bold);return t;}
        void heading(LinearLayout parent,String s){TextView t=text(s,20,true);t.setPadding(2,Ui.dp(a,20),2,Ui.dp(a,12));parent.addView(t);}
        void note(LinearLayout parent,String s){TextView t=text(s,14,false);t.setTextColor(Ui.muted(a));t.setPadding(Ui.dp(a,8),Ui.dp(a,18),Ui.dp(a,8),Ui.dp(a,18));parent.addView(t);}
        TextView button(LinearLayout parent,String s,Runnable task){TextView t=Ui.button(a,s,v->task.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=p.bottomMargin=Ui.dp(a,4);parent.addView(t,p);return t;}
        View loading(LinearLayout p){ProgressBar v=new ProgressBar(a);v.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(Ui.dp(a,36),Ui.dp(a,36));l.gravity=Gravity.CENTER;l.topMargin=l.bottomMargin=Ui.dp(a,30);p.addView(v,l);return v;}
